  const LOCALES = [["vi", "Tiếng Việt"], ["en", "English"], ["zh-Hans", "简体中文"], ["zh-Hant", "繁體中文"]];
  const NUMBER_LOCALE = { vi: "vi-VN", en: "en-US", "zh-Hans": "zh-CN", "zh-Hant": "zh-TW" };
  /* BR-I18N-01: ngôn ngữ mặc định theo thiết bị; không hỗ trợ thì dùng en. */
  function detect(lang) {
    const l = (lang || "").toLowerCase();
    if (l.startsWith("vi")) return "vi";
    if (/^zh-(tw|hk|mo|hant)/.test(l)) return "zh-Hant";
    if (l.startsWith("zh")) return "zh-Hans";
    return "en";
  }
  function make(locale) {
    return (key, vars) => {
      let s = (D[locale] && D[locale][key]) || D.en[key] || key;
      if (vars) Object.keys(vars).forEach((k) => (s = s.replace("{" + k + "}", vars[k])));
      return s;
    };
  }
  return { D, LOCALES, NUMBER_LOCALE, detect, make };
